//! Cargo-driven `localspl.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is localspl-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x72a60000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fef6000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fef6000000u64)),
        o => panic!("localspl-cargo: unsupported arch {o}"),
    };

    let static_libs: &[&str] = match arch.as_str() {
        "x86" => &["sdk/lib/skiplist/libskiplist16.a", "sdk/lib/libwine/libwine.a", "sdk/lib/skiplist/libskiplist_rust.a", "sdk/lib/crt/CMakeFiles/oldnames.dir/oldnames.a"],
        "x86_64" => &["sdk/lib/skiplist/libskiplist16.a", "sdk/lib/libwine/libwine.a", "sdk/lib/skiplist/libskiplist_rust.a", "sdk/lib/crt/CMakeFiles/oldnames.dir/oldnames.a"],
        "aarch64" => &["sdk/lib/skiplist/libskiplist16.a", "sdk/lib/libwine/libwine.a", "sdk/lib/skiplist/libskiplist_rust.a", "sdk/lib/crt/CMakeFiles/oldnames.dir/oldnames.a"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("localspl-rust")
        .resource_from_rc("win32ss/printing/providers/localspl/localspl.rc", "localspl_res")
        .spec2def("win32ss/printing/providers/localspl/localspl.spec", "localspl.dll")
        .spec_stubs()
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/advapi32_vista/advapi32_vista.spec", "advapi32_vista.dll", "advapi32_vista")
        .import_lib("dll/win32/netapi32/netapi32.spec", "netapi32.dll", "netapi32")
        .import_lib("dll/win32/rpcrt4/rpcrt4.spec", "rpcrt4.dll", "rpcrt4")
        .import_lib("dll/win32/secur32/secur32.spec", "secur32.dll", "secur32")
        .import_lib("win32ss/printing/base/spoolss/spoolss.spec", "spoolss.dll", "spoolss")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // cmake-built static libraries, reused until each has a cargo home.
        .static_libs(static_libs)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
